using HakutaiKagami.Core.Messaging;
using HakutaiKagami.Core.World;
namespace HakutaiKagami.Core.Contracts;
// Seconds-domain integration of local travel, delivered officer decisions and simultaneous contact losses.
public static class RegionalBattle
{
    public const string Ruleset = "regional-integrated-validation-v1";
    public static readonly EntityId Enemy = new("person:region-enemy");
    public static bool Enabled(ContractWorld w) => w.Definitions.Ruleset == Ruleset||RegionalScenery.Enabled(w)||ContinuousWorld.Enabled(w);
    public static bool Active(ContractWorld w) => Enabled(w) && w.Region!.Active;
    public static string Version(ContractWorld w) => ContractJson.CanonicalHash(new[] { ContinuousWorld.Enabled(w)?ContinuousWorld.Version:RegionalScenery.Enabled(w)?RegionalScenery.Version:FieldWorld.Version, "smooth-radius1000-swept-reservation-height-x-over5-v1", "physical-order-recognition-refusal-report-contact-simultaneous-morale25-retreat-v1", $"{w.Region!.PerForce}/{w.Region.Refuses}/{w.Region.LowMorale}" + (NpcWork.Enabled(w)?NpcWork.Contract+RegionalWork.Contract+ContractJson.CanonicalHash(RegionalWork.Roles):RegionalWork.Enabled(w)?RegionalWork.Contract+ContractJson.CanonicalHash(RegionalWork.Roles):AssessmentNotice.Enabled(w)?AssessmentNotice.Contract:MissionReview.Enabled(w)?MissionReview.Contract:IncomingMission.Enabled(w)?IncomingMission.Contract:MissionEntry.Enabled(w)?MissionEntry.Contract:OfficerLoop.Enabled(w)?OfficerLoop.Contract:"") });
    static EntityId[] Commanders => [ContractFixture.Officer, ContractFixture.Clerk, Enemy];
    static FieldPoint Initial(int group, int i, int count) => count == 3 ? (group == 0 ? FieldWorld.Initial(i) : group == 1 ? new(-25000, 5000 + (i == 0 ? 0 : i == 1 ? 10000 : -10000)) : new(65000, 15000 + i * 10000)) : new(group == 2 ? 55000 + (i % 3) * 10000 : -45000 + (i % 3) * 10000, group == 1 ? 15000 + (i / 3) * 10000 : -45000 + (i / 3) * 10000);
    public static ContractWorld Create(int count = 3, bool refuses = false, bool lowMorale = false) { if (count is not (3 or 12)) throw new ArgumentException("Supported scale3 or12 per force"); var w = FieldWorld.Create(); var org = new EntityId("org:region-enemy"); var army = new EntityId("army:region-enemy"); w.Definitions = w.Definitions with { Characters = [.. w.Definitions.Characters, new(Enemy, "検証敵将")], Organizations = [.. w.Definitions.Organizations, new(org, "検証敵勢力")], Armies = [.. w.Definitions.Armies, new(army, org, Enemy)] }; w.Characters = [.. w.Characters.Select(c => c.Id == ContractFixture.Clerk ? c with { WillObey = !refuses } : c), new(Enemy, LifeState.Adult, new("appearance:fixture"), 0)]; w.Locations = [.. w.Locations, new(Enemy, LocationKind.AtSite, ContractFixture.Castle, null, 0, 0, null, null, null, null, 0)]; w.ServiceBonds = [.. w.ServiceBonds, new(new("service:regional-clerk"), ContractFixture.Clerk, ContractFixture.Officer, "service", new("basis:service"), 0, long.MaxValue, 0)]; var units = new List<RegionalUnit>(); var states = new List<UnitState>(); for (int g = 0; g < 3; g++) for (int i = 0; i < count; i++) { var id = g == 0 && i < 3 ? FieldWorld.UnitIds[i] : g == 1 && i == 0 ? new EntityId("unit:clerk") : new("unit:region/" + g + "/" + i); int soldiers = i == 0 ? 40 : 30; var p = Initial(g, i, count); int morale = lowMorale && g == 0 ? 25 : 100; units.Add(new(id, Commanders[g], g == 2 ? 1 : 0, p, p, new(0, 1), p, p, [], soldiers, soldiers, morale, morale, "standing")); states.Add(new(id, g == 0 ? new("army:officer") : g == 1 ? new("army:clerk") : army, Commanders[g], g == 2 ? org : w.Definitions.Organizations[0].Id, soldiers, 0)); } w.Units = states.ToArray(); w.Region = new(count, refuses, lowMorale, true, 0, 0, false, units.ToArray(), [], [], [], []); w.WorldId = new("world:regional-integrated-validation-v1"); w.Definitions = w.Definitions with { Id = new("scenario:regional-integrated-validation-v1"), Ruleset = Ruleset }; w.Definitions = w.Definitions with { Version = Version(w) }; Sync(w); ContractValidation.Validate(w); return w; }
    public static FieldPoint Position(ContractWorld w, EntityId actor) => w.Region!.Units.FirstOrDefault(u => u.Commander == actor)?.Position ?? new(5000, 5000);
    static string MessageId(EntityId id) => "message:region/" + ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(id.Value));
    public static bool Handles(ContractWorld w, string message) { if (!Enabled(w)) return false; var m = w.Messaging.Messages.Single(m => m.Id == message); return m.Kind.StartsWith("region-", StringComparison.Ordinal) || m.Kind == "delivery-failure" && w.Region!.Deliveries.Any(d => d.Attempt == m.Body); }
    static bool Permits(ContractWorld w, RegionalRequest r, long at) => r.Actor == w.PlayerControl && r.Recipient != Enemy && Commanders.Contains(r.Recipient) && w.Characters.Single(c => c.Id == r.Actor).Life == LifeState.Adult && w.Grants.Any(g => g.Agent == r.Actor && g.Scope == ContractFixture.Castle && g.Actions.Contains(ActionKind.Move) && g.From <= at && at < g.Until) && (r.Actor == r.Recipient || w.ServiceBonds.Any(b => b.Subject == r.Recipient && b.Target == r.Actor && b.From <= at && at < b.Until));
    public static void Issue(ContractWorld w, RegionalRequest request)
    {
        if (!Active(w) || !EntityId.IsValid(request.Id.Value) || request.A == null || request.B == null || new[] { request.A.X, request.A.Y, request.B.X, request.B.Y }.Any(v => Math.Abs(v) > (ContinuousWorld.Enabled(w)?4000000000L:100000L) || !ContinuousWorld.Enabled(w)&&v< -60000) || !Enum.IsDefined(request.Action) || !Permits(w, request, w.ElapsedSeconds)) throw new InvalidDataException("Regional command unavailable"); if (request.Supersedes is { } prior && !w.Region!.Commands.Any(c => c.Request.Id == prior && c.Request.Actor == request.Actor && c.Request.Recipient == request.Recipient)) throw new InvalidDataException("Replacement lacks original command"); if (w.Requests.Any(r => r.Id == request.Id) || w.Field!.Orders.Any(o => o.Request.Id == request.Id) || w.TravelDecisions!.Any(d => d.Request.Id == request.Id)) throw new InvalidDataException("ID already used");
        FieldPoint address; if (request.Actor == request.Recipient) address = Position(w, request.Actor); else { var unit = w.Region!.Units.First(u => u.Commander == request.Recipient); address = w.Region.Sights.Where(s => s.Observer == request.Actor && s.Unit == unit.Id).OrderByDescending(s => s.At).FirstOrDefault()?.Position ?? throw new InvalidDataException("No known delivery address"); }
        var message = MessageId(request.Id); var cmd = new RegionalCommand(request, w.ElapsedSeconds, message, address, null, null, "in-transit"); w.Region = w.Region! with { Commands = [.. w.Region.Commands, cmd] }; if (request.Actor == request.Recipient) Apply(w, cmd); else Send(w, new(message, request.Id.Value, "region-order", request.Actor.Value, request.Recipient.Value, request.Id.Value, ContractFixture.Castle.Value, w.ElapsedSeconds), Position(w, request.Actor), address);
        Sync(w);
    }
    static void Send(ContractWorld w, MessageEnvelope message, FieldPoint origin, FieldPoint address) { var path = RegionalGround.Plan(origin, address, w.ElapsedSeconds, courier: true,scenery:RegionalScenery.Enabled(w),atlas:ContinuousWorld.Enabled(w)); long due = Math.Max(w.ElapsedSeconds + 1, path.LastOrDefault()?.EndAt ?? w.ElapsedSeconds + 1); MessageFlow.Send(w.Messaging, message, w.ElapsedSeconds, checked((int)(due - w.ElapsedSeconds))); var a = MessageFlow.Latest(w.Messaging, message.Id); w.Region = w.Region! with { Deliveries = [.. w.Region.Deliveries, new(a.Id, origin, address, path, due)] }; }
    static FieldLeg[] Reserve(ContractWorld w, RegionalUnit unit, FieldPoint goal, List<RegionalUnit> all) { var obstacles = all.Where(u => u.Id != unit.Id && u.Soldiers > 0).SelectMany(u => new[] { u.Position, u.Goal }).Distinct().Where(p => RegionalGround.Distance(p, unit.Position) >= 2000).ToArray(); var path = RegionalGround.Plan(unit.Position, goal, w.ElapsedSeconds, obstacles,scenery:RegionalScenery.Enabled(w),atlas:ContinuousWorld.Enabled(w)); for (int wait = 0; wait <= 600; wait++) { var shifted = path.Select(l => l with { StartAt = l.StartAt + wait, EndAt = l.EndAt + wait }).ToArray(); var end = shifted.LastOrDefault()?.EndAt ?? w.ElapsedSeconds; bool conflict = all.Where(u => u.Id != unit.Id && u.Soldiers > 0).Any(u => RegionalGround.Conflict(shifted, unit.Position, u.Route, u.RouteOrigin, w.ElapsedSeconds, Math.Max(end, u.Route.LastOrDefault()?.EndAt ?? w.ElapsedSeconds) + 1)); if (!conflict) return shifted; } throw new InvalidDataException("Reservation blocked; hold and query"); }
    static void Apply(ContractWorld w, RegionalCommand command)
    {
        var r = command.Request; var now = w.ElapsedSeconds; string result = "applied"; var units = w.Region!.Units.ToList(); try
        {
            if (!Permits(w, r, now)) result = "authority-refused";
            else if (!w.Characters.Single(c => c.Id == r.Recipient).WillObey) result = "refused";
            else if (w.Region.Commands.Any(c => c.Request.Supersedes == r.Id && c.AppliedAt != null)) result = "superseded";
            else
            {
                var group = units.Where(u => u.Commander == r.Recipient).ToArray(); if (group.Any(u => u.Soldiers == 0 || u.Phase == "routed") && r.Action != RegionalAction.Retreat) throw new InvalidDataException("Force unable"); for (int i = 0; i < group.Length; i++)
                {
                    var u = units.Single(x => x.Id == group[i].Id); FieldPoint goal; if (r.Action == RegionalAction.Retreat) goal = u.Home; else if (r.Action == RegionalAction.Hold) goal = u.Position; else if (r.Action == RegionalAction.Engage) { var enemy = w.Region.Sights.Where(s => s.Observer == r.Recipient && w.Region.Units.Single(x => x.Id == s.Unit).Side != u.Side && s.Soldiers > 0).OrderBy(s => s.Unit.Value, StringComparer.Ordinal).ToArray(); if (enemy.Length == 0) throw new InvalidDataException("No observed enemy"); var target = enemy[i % enemy.Length].Position; var d = Math.Max(1, RegionalGround.Distance(u.Position, target)); goal = new(target.X + (u.Position.X - target.X) * 4000 / d, target.Y + (u.Position.Y - target.Y) * 4000 / d); } else { if (RegionalGround.Distance(r.A, r.B) < 10000) throw new InvalidDataException("Line too short"); goal = new(r.A.X + (r.B.X - r.A.X) * i / Math.Max(1, group.Length - 1), r.A.Y + (r.B.Y - r.A.Y) * i / Math.Max(1, group.Length - 1)); }
                    FieldLeg[] route; try { route = Reserve(w, u, goal, units); } catch (InvalidDataException e) { throw new InvalidDataException(u.Id.Value + " -> " + goal + ": " + e.Message, e); }
                    var next = u with { Goal = goal, RouteOrigin = u.Position, Route = route, Phase = r.Action == RegionalAction.Retreat ? "withdrawing" : route.Length > 0 ? "marching" : "standing" }; units[units.FindIndex(x => x.Id == u.Id)] = next;
                }
                w.Region = w.Region with { Units = units.ToArray(), Hostile = w.Region.Hostile || r.Action == RegionalAction.Engage };
            }
        }
        catch (InvalidDataException) { result = "blocked-hold"; }
        w.Region = w.Region! with { Commands = w.Region.Commands.Select(c => c.Request.Id == r.Id ? c with { RecognizedAt = now, AppliedAt = result == "applied" ? now : null, Result = result } : c).ToArray() }; Reply(w, command, result);
    }
    static void Reply(ContractWorld w, RegionalCommand command, string result) { var r = command.Request; var now = w.ElapsedSeconds; if (r.Actor != r.Recipient) { var original = w.Region!.Deliveries.First(d => w.Messaging.Attempts.Single(a => a.Id == d.Attempt).MessageId == command.Message); Send(w, new("message:region-report/" + ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(r.Id.Value)), r.Id.Value, "region-report", r.Recipient.Value, r.Actor.Value, result, ContractFixture.Castle.Value, now), Position(w, r.Recipient), original.Origin); } }

    public static void SetActive(ContractWorld w, bool active) { if (!Enabled(w) || w.Region!.Active == active) throw new InvalidDataException("No transition"); if (active) { if(ContinuousWorld.Enabled(w)){ContinuousWorld.Enter(w);return;} if (w.Locations.Single(l => l.Actor == w.PlayerControl).Site != ContractFixture.Castle || TravelWorld.Active(w)) throw new InvalidDataException("Not at anchor"); w.Region = w.Region with { Active = true, Since = w.ElapsedSeconds, Tick = w.ElapsedSeconds }; Sync(w); } else { if (w.Region.Hostile || w.Region.Units.Any(u => u.Route.Any(l => l.EndAt > w.ElapsedSeconds)) || w.Region.Units.Where(u => u.Commander == w.PlayerControl).Any(u => u.Position != u.Home) || w.Messaging.Attempts.Any(a => a.Status == AttemptStatus.InTransit && Handles(w, a.MessageId))) throw new InvalidDataException("Return and finish pending messages"); w.Region = w.Region with { Active = false }; w.Locations = w.Locations.Select(l => l.Actor == w.PlayerControl ? new LocationState(l.Actor, LocationKind.AtSite, ContinuousWorld.Enabled(w)?RegionalCampaign.Site(w.Atlas!.Anchor):ContractFixture.Castle, null, 0, 0, null, null, null, null, w.CommitSequence) : l).ToArray(); } }
    public static void BeforeMessages(ContractWorld w) { if (!Active(w)) return; foreach (var d in w.Region!.Deliveries) { var a = w.Messaging.Attempts.Single(a => a.Id == d.Attempt); if (a.Status != AttemptStatus.InTransit || a.DueAt != w.ElapsedSeconds) continue; if (RegionalGround.Distance(Position(w, new(a.ReceiverId)), d.Address) > 1500) w.Messaging.Attempts = w.Messaging.Attempts.Select(x => x.Id == a.Id ? x with { FailOnArrival = true } : x).ToArray(); } }
    public static void AfterMessages(ContractWorld w)
    {
        if (!Enabled(w)) return; var ready = w.Region!.Commands.Where(c => c.Result == "in-transit" && MessageFlow.Knows(w.Messaging, c.Message, c.Request.Recipient.Value)).ToArray(); foreach (var c in ready) { bool conflict = ready.Any(x => x.Request.Id != c.Request.Id && x.Request.Recipient == c.Request.Recipient && x.Request.Supersedes != c.Request.Id && c.Request.Supersedes != x.Request.Id); if (conflict) { w.Region = w.Region with { Commands = w.Region.Commands.Select(x => x.Request.Id == c.Request.Id ? x with { RecognizedAt = w.ElapsedSeconds, Result = "conflict-hold" } : x).ToArray() }; Reply(w, c, "conflict-hold"); } else Apply(w, c); }
        foreach (var d in w.Region.Deliveries.ToArray()) { var a = w.Messaging.Attempts.Single(a => a.Id == d.Attempt); var m = w.Messaging.Messages.Single(m => m.Id == a.MessageId); if (a.FailureAt != w.ElapsedSeconds || m.Kind == "delivery-failure") continue; var id = "message:region-failure/" + ContractJson.Hash(System.Text.Encoding.UTF8.GetBytes(a.Id)); if (w.Messaging.Messages.Any(x => x.Id == id)) continue; var path = RegionalGround.Plan(d.Address, d.Origin, w.ElapsedSeconds, courier: true,scenery:RegionalScenery.Enabled(w),atlas:ContinuousWorld.Enabled(w)); var due = Math.Max(w.ElapsedSeconds + 1, path.LastOrDefault()?.EndAt ?? w.ElapsedSeconds + 1); MessageFlow.ReportFailure(w.Messaging, id, a.Id, m.SenderId, w.ElapsedSeconds, checked((int)(due - w.ElapsedSeconds))); var report = MessageFlow.Latest(w.Messaging, id); w.Region = w.Region with { Deliveries = [.. w.Region.Deliveries, new(report.Id, d.Address, d.Origin, path, due)] }; }
        Sync(w);
    }
    public static void Tick(ContractWorld w)
    {
        if (!Active(w)) return; var s = w.Region!; if (s.Tick + 1 != w.ElapsedSeconds) throw new InvalidDataException("Regional clock skipped a second"); var now = w.ElapsedSeconds; var units = s.Units.Select(u => { var p = RegionalGround.At(u.Route, u.RouteOrigin, now); var dx = p.X - u.Position.X; var dy = p.Y - u.Position.Y; return u with { Position = p, Heading = dx == 0 && dy == 0 ? u.Heading : new(dx, dy), Phase = u.Phase == "marching" && u.Route.LastOrDefault()?.EndAt <= now ? "standing" : u.Phase }; }).ToArray();
        // A newly stopped/contacting unit invalidates earlier time reservations. Stop both crossing movers at their previous safe positions.
        for (int pass = 0; pass < units.Length; pass++) { var blocked = new HashSet<EntityId>(); for (int i = 0; i < units.Length; i++) for (int j = i + 1; j < units.Length; j++) { var a = units[i]; var b = units[j]; if (a.Soldiers == 0 || b.Soldiers == 0) continue; var oldA = s.Units[i].Position; var oldB = s.Units[j].Position; FieldLeg[] ar = oldA == a.Position ? [] : [new(oldA, a.Position, now - 1, now, 1, "sweep")]; FieldLeg[] br = oldB == b.Position ? [] : [new(oldB, b.Position, now - 1, now, 1, "sweep")]; if (RegionalGround.Conflict(ar, oldA, br, oldB, now - 1, now)) { if (a.Position != oldA) blocked.Add(a.Id); if (b.Position != oldB) blocked.Add(b.Id); } } if (blocked.Count == 0) break; units = units.Select((u, i) => blocked.Contains(u.Id) ? u with { Position = s.Units[i].Position, RouteOrigin = s.Units[i].Position, Goal = s.Units[i].Position, Route = [], Phase = "blocked" } : u).ToArray(); }
        var losses = new List<RegionalLoss>(); if (s.Hostile) foreach (var u in units.Where(u => u.Soldiers > 0)) { var enemies = units.Where(v => v.Soldiers > 0 && v.Side != u.Side && v.Phase is not ("routed" or "withdrawing") && RegionalGround.Distance(u.Position, v.Position) <= 4500 && Math.Abs(RegionalGround.Height(u.Position,RegionalScenery.Enabled(w),ContinuousWorld.Enabled(w)) - RegionalGround.Height(v.Position,RegionalScenery.Enabled(w),ContinuousWorld.Enabled(w))) <= 3000).ToArray(); if (enemies.Length > 0) losses.Add(new(now, u.Id, Math.Min(u.Soldiers, enemies.Sum(e => Math.Max(1, e.Soldiers / 10))), Math.Min(u.Morale, enemies.Length * 8))); }
        var list = units.ToList(); foreach (var hit in losses) { int i = list.FindIndex(u => u.Id == hit.Unit); var u = list[i]; var soldiers = u.Soldiers - hit.Soldiers; var morale = u.Morale - hit.Morale; list[i] = u with { Soldiers = soldiers, Morale = morale, RouteOrigin = u.Position, Route = [], Goal = u.Position, Phase = soldiers == 0 ? "destroyed" : "engaged" }; }
        w.Region = s with { Tick = now, Units = list.ToArray(), Losses = [.. s.Losses, .. losses] }; foreach (var u in w.Region.Units.Where(u => u.Soldiers > 0 && u.Morale <= 25 && losses.Any(l => l.Unit == u.Id) && u.Phase is not ("routed" or "withdrawing")).ToArray()) { FieldLeg[] route; try { route = Reserve(w, u, u.Home, w.Region.Units.ToList()); } catch (InvalidDataException) { route = []; } w.Region = w.Region with { Units = w.Region.Units.Select(x => x.Id == u.Id ? x with { RouteOrigin = u.Position, Route = route, Goal = route.Length == 0 ? u.Position : u.Home, Phase = "routed" } : x).ToArray() }; }
        if (w.Region.Units.Where(u => u.Side == 1).All(u => u.Soldiers == 0 || u.Phase == "routed")) w.Region = w.Region with { Hostile = false }; Sync(w);
    }
    public static void Sync(ContractWorld w)
    {
        if (!Active(w)) return; var s = w.Region!; w.Units = w.Units.Select(u => s.Units.FirstOrDefault(x => x.Id == u.Id) is { } state ? u with { Soldiers = state.Soldiers, Revision = w.CommitSequence } : u).ToArray(); foreach (var commander in Commanders) { var p = Position(w, commander); var world = FieldWorld.ToWorld(p); var geo = JapanGeography.Inverse(new(world.EastMm, world.NorthMm)); w.Locations = w.Locations.Select(l => l.Actor == commander ? new LocationState(l.Actor, LocationKind.AtPosition, null, null, 0, 0, geo.LatitudeE7, geo.LongitudeE7, RegionalGround.Height(p,RegionalScenery.Enabled(w),ContinuousWorld.Enabled(w)), Version(w), w.CommitSequence) : l).ToArray(); }
        var sights = s.Sights.ToList(); foreach (var observer in Commanders) foreach (var u in s.Units.Where(u => u.Commander == observer || RegionalGround.Distance(Position(w, observer), u.Position) <= 80000)) { sights.RemoveAll(x => x.Observer == observer && x.Unit == u.Id); sights.Add(new(observer, u.Id, u.Position, u.Heading, u.Soldiers, u.Morale, u.Phase, w.ElapsedSeconds)); }
        w.Region = s with { Sights = sights.ToArray() };
    }
    public static RegionalView[] View(ContractWorld w, EntityId observer) => w.Region!.Sights.Where(s => s.Observer == observer).Select(s => new RegionalView(s.Unit, s.Position, s.Heading, RegionalGround.Height(s.Position,RegionalScenery.Enabled(w),ContinuousWorld.Enabled(w)), s.Soldiers, s.Morale, s.Phase, s.At, s.At == w.ElapsedSeconds)).ToArray();
    public static string Status(ContractWorld w, RegionalCommand c, EntityId observer) => observer == c.Request.Recipient ? c.Result : w.Messaging.Messages.Any(m => m.Kind == "region-report" && m.CorrelationId == c.Request.Id.Value && MessageFlow.Knows(w.Messaging, m.Id, observer.Value)) ? c.Result : MessageFlow.FailureKnown(w.Messaging, MessageFlow.Latest(w.Messaging, c.Message).Id, observer.Value) ? "失敗報告を受領" : "発送済・結果未確認";
    public static BranchView BranchView(ContractWorld w, ActorView knowledge) { var u = w.Region!.Units.First(u => u.Commander == knowledge.Observer); var next = RegionalGround.At(u.Route, u.RouteOrigin, w.ElapsedSeconds + 1); var p = FieldWorld.ToWorld(u.Position); var n = FieldWorld.ToWorld(next); return new(knowledge, p, new(u.Heading.X, u.Heading.Y), u.Route.Sum(l => w.ElapsedSeconds >= l.EndAt ? RegionalGround.Distance(l.From, l.To) : 0), u.Route.Length > 0 && w.ElapsedSeconds < u.Route[^1].EndAt, u.Route.LastOrDefault()?.EndAt, [], BranchRoutes.KnownBlocked(w, knowledge.Observer), n, RegionalGround.Distance(u.Position, next)); }
    public static void Validate(ContractWorld w)
    {
        var s = w.Region ?? throw new InvalidDataException("Missing regional module"); if (s.PerForce is not (3 or 12) || s.Units.Length != s.PerForce * 3 || s.Tick > w.ElapsedSeconds || s.Tick < 0 || s.Active && s.Tick != w.ElapsedSeconds || s.Commands.Select(c => c.Request.Id).Distinct().Count() != s.Commands.Length) throw new InvalidDataException("Regional clock/config invalid"); if (s.Since < 0 || s.Since > w.ElapsedSeconds || s.Losses.Any(l => l.At <= 0 || l.At > w.ElapsedSeconds || l.Soldiers <= 0 || l.Morale < 0)) throw new InvalidDataException("Invalid effect clock"); if (s.Losses.Select(l => (l.At, l.Unit)).Distinct().Count() != s.Losses.Length) throw new InvalidDataException("Duplicate combat effect"); foreach (var u in s.Units) { RegionalGround.ValidatePath(u.Route, u.RouteOrigin, u.Goal,scenery:RegionalScenery.Enabled(w),atlas:ContinuousWorld.Enabled(w)); if (!RegionalGround.Walkable(u.Position,RegionalScenery.Enabled(w),ContinuousWorld.Enabled(w)) || u.Position != RegionalGround.At(u.Route, u.RouteOrigin, w.ElapsedSeconds) || u.Soldiers < 0 || u.Morale < 0 || u.Morale > 100 || u.InitialSoldiers - u.Soldiers != s.Losses.Where(l => l.Unit == u.Id).Sum(l => l.Soldiers) || u.InitialMorale - u.Morale != s.Losses.Where(l => l.Unit == u.Id).Sum(l => l.Morale) || w.Units.Single(x => x.Id == u.Id).Soldiers != u.Soldiers || u.Soldiers == 0 && u.Phase != "destroyed") throw new InvalidDataException("Regional position/loss mismatch"); foreach (var l in u.Route) if (l.StartAt < 0 || l.EndAt <= l.StartAt || !RegionalGround.Walkable(l.From,RegionalScenery.Enabled(w),ContinuousWorld.Enabled(w)) || !RegionalGround.Walkable(l.To,RegionalScenery.Enabled(w),ContinuousWorld.Enabled(w))) throw new InvalidDataException("Regional route invalid"); }
        for (int i = 0; i < s.Units.Length; i++) for (int k = i + 1; k < s.Units.Length; k++) if (s.Units[i].Soldiers > 0 && s.Units[k].Soldiers > 0 && RegionalGround.Distance(s.Units[i].Position, s.Units[k].Position) < 2000) throw new InvalidDataException("Units overlap");
        foreach (var d in s.Deliveries) { RegionalGround.ValidatePath(d.Path, d.Origin, d.Address, true,RegionalScenery.Enabled(w),ContinuousWorld.Enabled(w)); var a = w.Messaging.Attempts.Single(a => a.Id == d.Attempt); if (a.DueAt != d.DueAt || d.DueAt <= a.SentAt || d.Path.Length > 0 && (d.Path[0].From != d.Origin || d.Path[0].StartAt != a.SentAt || d.Path[^1].To != d.Address || d.Path[^1].EndAt != d.DueAt)) throw new InvalidDataException("Regional courier mismatch"); }
        if (s.Deliveries.Select(d => d.Attempt).Distinct().Count() != s.Deliveries.Length || s.Deliveries.Length != w.Messaging.Attempts.Count(a => Handles(w, a.MessageId))) throw new InvalidDataException("Missing/duplicate regional courier");
        foreach (var c in s.Commands) { if (c.AppliedAt > w.ElapsedSeconds || c.RecognizedAt > w.ElapsedSeconds || c.IssuedAt < 0 || c.IssuedAt > w.ElapsedSeconds || c.AppliedAt < c.IssuedAt || c.RecognizedAt < c.IssuedAt || c.AppliedAt != null && c.Result != "applied" || c.Request.Actor != c.Request.Recipient && c.RecognizedAt != null && !MessageFlow.Knows(w.Messaging, c.Message, c.Request.Recipient.Value)) throw new InvalidDataException("Order applied without recognition"); }
        if (s.Active) foreach (var actor in Commanders) { var u = s.Units.First(u => u.Commander == actor); var p = FieldWorld.ToWorld(u.Position); var geo = JapanGeography.Inverse(new(p.EastMm, p.NorthMm)); var l = w.Locations.Single(l => l.Actor == actor); if (l.Kind != LocationKind.AtPosition || l.LatitudeE7 != geo.LatitudeE7 || l.LongitudeE7 != geo.LongitudeE7 || l.HeightMm != RegionalGround.Height(u.Position,RegionalScenery.Enabled(w),ContinuousWorld.Enabled(w))) throw new InvalidDataException("Displayed height/location not authoritative"); }
    }
}
